package com.esn.smp.gameplay;
import com.esn.smp.data.ESNDataStore;import org.bukkit.*;import org.bukkit.command.*;import org.bukkit.entity.Player;import java.time.Duration;
public final class ProfileCommand implements CommandExecutor{private final ESNDataStore data;public ProfileCommand(ESNDataStore d){data=d;}public boolean onCommand(CommandSender s,Command c,String l,String[] a){if(!(s instanceof Player p))return true;try{long bal=data.getBalance(p),ticks=p.getStatistic(Statistic.PLAY_ONE_MINUTE),mins=ticks/1200;int kills=p.getStatistic(Statistic.PLAYER_KILLS),deaths=p.getStatistic(Statistic.DEATHS);String rank=p.isOp()?"Owner":bal>=100000?"MVP":bal>=25000?"VIP":"Member";p.sendMessage(ChatColor.GOLD+"--- "+p.getName()+"'s ESN Profile ---");p.sendMessage(ChatColor.YELLOW+"Rank: "+ChatColor.WHITE+rank);p.sendMessage(ChatColor.YELLOW+"Balance: "+ChatColor.WHITE+bal+" Coins");p.sendMessage(ChatColor.YELLOW+"Playtime: "+ChatColor.WHITE+(mins/60)+"h "+(mins%60)+"m");p.sendMessage(ChatColor.YELLOW+"Kills / Deaths: "+ChatColor.WHITE+kills+" / "+deaths);}catch(Exception e){p.sendMessage(ChatColor.RED+"Profile unavailable.");}return true;}}
